export function BrandGlyph({ name, className, title }) {
  const brand = BRANDS[name];
  if (!brand) return null;
  return (
    <svg
      viewBox="0 0 24 24"
      className={className}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title ? brand.title : undefined}
      aria-hidden={title ? undefined : "true"}
    >
      <path d={brand.path} />
    </svg>
  );
}

export function hasBrand(name) {
  return Boolean(BRANDS[name]);
}
